// HomeBody Service Worker. The cache name is the release identifier: VERSION is a content hash
// written by scripts/stamp-sw.mjs (npm run stamp), never edited by hand.
// >>> stamp-sw:begin (generated by scripts/stamp-sw.mjs; run `npm run stamp`, do not edit)
const VERSION = 'c0ecc22fe0dd';
const PRECACHE = ["fonts/inter-latin.woff2", "fonts/oswald-latin.woff2", "icon-192.png", "icon-512.png", "index.html", "manifest.json"];
// <<< stamp-sw:end
const CACHE = 'homebody-' + VERSION;

// All paths in PRECACHE are relative to this script, so the GitHub Pages sub-path just works.
const INDEX = 'index.html';

self.addEventListener('install', event => {
  self.skipWaiting(); // installs immediately (removed in T4, with the update flow)
  // 'reload' bypasses the HTTP cache so one release never mixes files. No catch: if any file
  // fails the install fails and the previous worker and cache stay in charge (never a partial cache).
  event.waitUntil(
    caches.open(CACHE).then(cache =>
      cache.addAll(PRECACHE.map(u => new Request(u, { cache: 'reload' })))
    )
  );
});

self.addEventListener('activate', event => {
  // Only this app's old caches: the github.io origin is shared with other projects.
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(
        keys.filter(k => k.startsWith('homebody-') && k !== CACHE).map(k => caches.delete(k))
      )
    ).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // never intercept third parties

  if (req.mode === 'navigate') {
    // The shell is one document: serve the precached index.html whatever the query string.
    event.respondWith(
      caches.open(CACHE).then(cache =>
        cache.match(INDEX, { ignoreSearch: true }).then(hit => hit || fetch(req))
      )
    );
    return;
  }
  event.respondWith(
    caches.open(CACHE).then(cache =>
      cache.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req))
    )
  );
});

self.addEventListener('message', event => {
  if (event.data === 'skipWaiting') self.skipWaiting();
});
